import{_ as n,o as a,c as e,a2 as t}from"./chunks/framework.CdjpmwdR.js";const c=JSON.parse('{"title":"Infrastructural Integrity: Scaling Beyond the Monolith.","description":"Parallels between distributed systems and modular engineering.","frontmatter":{"category":"DevOps","date":"Oct 18, 2024","title":"Infrastructural Integrity: Scaling Beyond the Monolith.","description":"Parallels between distributed systems and modular engineering.","image":"https://lh3.googleusercontent.com/aida-public/AB6AXuDzKWWVxz0DGkjl-0UeiovPLpjKi4Fbn41BHqQkcd1WKNoO89NjE2vAaB_dFriwDLH_6nag_Lsjocv_XM2U_0j-7g1f17YwIaXSqdl6JQb8tCJZNwBONiGo5pg5BoS_MtMLOK-U1hJbSwi4cekhDiO_zuOgJHWb41JdFq4j_1MP0_0vGrbAdNZrrZCFzLm5yJsdh8F5rl5tF2HAvJ5fA7ezbMJI5FUZx0Le_2AfmgQH9pPo4Z-_bRI1k5gA0ByE1nyoCVtq7UTpesc"},"headers":[],"relativePath":"blogs/2026/202602-domain-spec-agents.md","filePath":"blogs/2026/202602-domain-spec-agents.md"}'),i={name:"blogs/2026/202602-domain-spec-agents.md"};function l(r,s,o,p,g,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="agents-驱动领域建模" tabindex="-1">Agents 驱动领域建模 <a class="header-anchor" href="#agents-驱动领域建模" aria-label="Permalink to &quot;Agents 驱动领域建模&quot;">​</a></h1><p><strong>DomainSpec 解决的是“上下文与建模意图在交付过程中逐步失真”这个问题。</strong></p><p>团队最初说清楚了需求，到了架构、开发、测试阶段却逐步偏离原意。它不是另一套“写文档的方法”，而是一套让同一份上下文从业务讨论一路延续到执行与验证的框架。</p><p><strong>它的核心很直接：先定边界，再定流程。</strong></p><p>先用 DDD 划定领域边界，明确哪些概念属于哪个上下文；再用工序设计制定标准流程，明确每一步的输入、输出和校验点。边界和流程一旦被写清楚，Agent 才能高效执行，而不是靠猜。</p><p>即使没有 Agent，这个问题也一直存在：需求会在架构、开发和测试之间逐步走样，上下文会在一次次交接里慢慢丢失。</p><p>Agent 不是根因，只是把速度拉高了。问题会更早暴露，也更容易被放大。没有边界的速度，只会更快地产生偏差。DomainSpec 的价值，就是先把边界、规则和交接关系固定下来。</p><h2 id="统一语言和上下文" tabindex="-1">“统一语言和上下文” <a class="header-anchor" href="#统一语言和上下文" aria-label="Permalink to &quot;“统一语言和上下文”&quot;">​</a></h2><p><strong>这正好击中 DDD 最难落地的地方：统一语言。</strong></p><p>领域专家、架构师、开发者、验证者经常在说同一个词时指向不同对象，或者面对同一个对象用了不同名字。人会因此误解，Agent 只会把这种误解放大。</p><p>DomainSpec 把统一语言从“会议共识”变成可传递的工件，再把这些工件持续传到后续层级，让 Agent 的上下文始终和 DDD 的上下文保持一致。</p><ol><li><p><strong>这里的“上下文”不是背景材料，而是决策的边界条件。</strong></p><p>DDD 里的 bounded context，不只是业务建模单元，也是 Agent 协作单元；领域词汇表不只是给人读的说明，也是提示词、任务规格和验证标准的锚点。</p><p>上下文一旦变化，就必须通过显式工件传递，而不是靠聊天记录里的模糊补充。</p></li><li><p><strong>分层不是为了形式完整，而是为了防止语义漂移。</strong></p><p>规格层负责定义含义、结构和流程，执行层负责实现和验证。反馈也不能绕开上游模型，而要通过显式 Change Request 回流。</p><p>这样系统修正的是规格本身，不是让实现偷偷改写原始意图。</p></li></ol><hr><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph SPEC[规格层]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D[DDD 划定领域边界]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        P[工序制定标准流程]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C[统一语言 与共享上下文]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        P --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; DEV[Agent 在清晰任务上下文中执行]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DEV --&gt; VAL[验证交付结果是否符合意图]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    VAL -. 显式反馈与变更请求 .-&gt; C</span></span></code></pre></div><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><h3 id="human-led-agent-assisted" tabindex="-1">human-led, agent-assisted <a class="header-anchor" href="#human-led-agent-assisted" aria-label="Permalink to &quot;human-led, agent-assisted&quot;">​</a></h3><ul><li><strong>Domain Analysis Assistant</strong><ul><li><strong>职责：</strong> 定义业务领域模型，并在各类领域工件之间保持术语一致。</li><li><strong>产物：</strong> Glossary、Four-Color Model、Event Map、Context Map。</li></ul></li><li><strong>Architecture Design Assistant</strong><ul><li><strong>职责：</strong> 把领域边界转换成系统级与服务级架构，并明确约束条件。</li><li><strong>产物：</strong> System Context、Service Decomposition、Communication Map、NFR Analysis、ADR、服务级组件设计。</li></ul></li><li><strong>Process Design Assistant</strong><ul><li><strong>职责：</strong> 把架构约束进一步转成可复用工序和可执行的 Story。</li><li><strong>产物：</strong> Procedure Catalog、Story Spec、流程一致性校验结果。</li></ul></li></ul><h3 id="agent-led-human-reviewed" tabindex="-1">agent-led, human-reviewed <a class="header-anchor" href="#agent-led-human-reviewed" aria-label="Permalink to &quot;agent-led, human-reviewed&quot;">​</a></h3><ul><li><strong>Developer</strong><ul><li><strong>职责：</strong> 在架构和工序约束下实现已确认的 Story。</li><li><strong>产物：</strong> Implementation Plan、业务代码、单元测试、开发校验报告。</li></ul></li><li><strong>Validator</strong><ul><li><strong>职责：</strong> 以黑盒方式验证交付结果，并把缺口反馈回交付层。</li><li><strong>产物：</strong> Test Plan、测试代码、测试报告、缺陷类 Change Request。</li></ul></li></ul><p><strong>一句话总结：</strong> DDD 负责划边界，工序负责定流程，Agent 只有在上下文持续统一时才能真正高效，而 DomainSpec 的作用就是把这份上下文固定下来、传递下去、在反馈中持续校正。</p><hr><blockquote><p><strong>项目地址：</strong> <a href="https://github.com/Anddd7/domain-spec-agents" target="_blank" rel="noreferrer">https://github.com/Anddd7/domain-spec-agents</a></p><p><strong>示例地址：</strong> <a href="https://github.com/Anddd7/domain-spec-examples/pulls" target="_blank" rel="noreferrer">https://github.com/Anddd7/domain-spec-examples/pulls</a></p></blockquote>`,22)])])}const u=n(i,[["render",l]]);export{c as __pageData,u as default};
